WHERE NOT EXISTS (SELECT 1 FROM `product_alternative` WHERE `product_id`=(SELECT `id` FROM `product` WHERE `franchise_code`='fann' AND `sku`='FANN-P030') AND `alternative_product_id`=(SELECT `id` FROM `product` WHERE `franchise_code`='fann' AND `sku`='FANN-P021'));

COMMIT;
